// #define USE_CAMERA

vec2 spherical_map(vec3 p) {
    vec2 uv = vec2(atan(p.z, p.x), asin(p.y));
    uv *= vec2(1.0 / TAU, 1.0 / PI); uv += 0.5;
    return uv;
}

vec3 spherical_map(vec2 uv) {
    uv -= 0.5; uv *= vec2(TAU, PI);
    vec2 s = sin(uv), c = cos(uv);
    return vec3(c.x*c.y, s.y, s.x*c.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv    = fragCoord / iResolution.xy;
    vec2 mouse = iMouse.xy / iResolution.xy;

    if (all(equal(mouse, vec2(0)))) mouse = vec2(0.5);

#if defined(USE_CAMERA)
    camera cam;
    cam.lookfrom = vec3(0, 0, 0);
    cam.lookat   = CameraRotation((mouse - 0.5) * vec2(PI)) * vec3(0, 0, 1);
    cam.aspect   = iResolution.x / iResolution.y;
    cam.vfov     = 50.0;
    cam.vup      = vec3(0, 1, 0);
    cam.focus    = 1.0;
    cam.aperture = 0.0;

    vec3 p = spherical_map(uv);

    vec2 uvv = spherical_map(p);

    ray r = get_ray(cam, uvv, vec3(1));

    vec3 col = texture(iChannel0, r.direction).rgb;
#else
    vec3 p = spherical_map(uv);
    p *= CameraRotation((mouse - 0.5) * vec2(PI));

    vec3 col = texture(iChannel0, p).rgb;
#endif

    fragColor = vec4(col, 1.0);
}

